3	import { useMemo, useState, type FormEvent } from "react";
4	import { useRouter } from "next/navigation";
5	import { toast } from "sonner";
6	import { Button } from "@/components/ui/button";
7	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
8	import { Input } from "@/components/ui/input";
9	import { Label } from "@/components/ui/label";
10	import {
11	  Select,
12	  SelectContent,
13	  SelectItem,
14	  SelectTrigger,
15	  SelectValue,
16	} from "@/components/ui/select";
17	import {
18	  Table,
19	  TableBody,
20	  TableCell,
21	  TableFooter,
22	  TableHead,
23	  TableHeader,
24	  TableRow,
25	} from "@/components/ui/table";
26	import { generateSchedule, type ScheduledInvoice } from "@/lib/billing";
27	import { formatSen, parseRinggitToSen } from "@/lib/money";
28	import { callApi } from "./api";
29	
30	type UnitOption = { id: string; name: string };
31	type TenantOption = { id: string; fullName: string; email: string };
32	
33	const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
34	// A schedule can legitimately be long (years of months); render a bounded number of rows, total stays exact.
35	const MAX_PREVIEW_ROWS = 120;
36	
37	type Preview =
38	  | { kind: "hint"; message: string }
39	  | { kind: "error"; message: string }
40	  | { kind: "ok"; rows: ScheduledInvoice[]; totalSen: number };
41	
42	// Pure function of the form values. Dates stay "YYYY-MM-DD" strings (never new Date(string), R52) and
43	// money goes through parseRinggitToSen; the thrown messages of generateSchedule are shown as hints.
44	function buildPreview(startDate: string, endDate: string, rent: string, deposit: string): Preview {
45	  if (!ISO_DATE.test(startDate) || !ISO_DATE.test(endDate) || rent.trim() === "") {
46	    return { kind: "hint", message: "Choose a start date, an end date and the monthly rent to see the invoice schedule." };
47	  }
48	  let monthlyRentSen: number;
49	  try {
50	    monthlyRentSen = parseRinggitToSen(rent);
51	  } catch {
52	    return { kind: "error", message: "Monthly rent must be an amount like 1,500.00." };
53	  }
54	  let depositSen = 0;
55	  if (deposit.trim() !== "") {
56	    try {
57	      depositSen = parseRinggitToSen(deposit);
58	    } catch {
59	      return { kind: "error", message: "Deposit must be an amount like 3,000.00, or empty for no deposit." };
60	    }
61	  }
62	  try {
63	    const rows = generateSchedule({ startDate, endDate, monthlyRentSen, depositSen });
64	    return { kind: "ok", rows, totalSen: rows.reduce((sum, r) => sum + r.amountSen, 0) };
65	  } catch (e) {
66	    return { kind: "error", message: e instanceof Error ? e.message : "These values do not make a valid lease." };
67	  }
68	}
69	
70	function kindLabel(r: ScheduledInvoice): string {
71	  return r.kind === "deposit" ? "Deposit" : `Rent ${(r.periodIndex ?? 0) + 1}`;
72	}
73	
74	export function NewLeaseForm({ units, tenants }: { units: UnitOption[]; tenants: TenantOption[] }) {
75	  const router = useRouter();
76	  const [unitId, setUnitId] = useState<string | null>(null);
77	  const [tenantId, setTenantId] = useState<string | null>(null);
78	  const [startDate, setStartDate] = useState("");
79	  const [endDate, setEndDate] = useState("");
80	  const [rent, setRent] = useState("");
81	  const [deposit, setDeposit] = useState("");
82	  const [submitting, setSubmitting] = useState(false);
83	
84	  const preview = useMemo(() => buildPreview(startDate, endDate, rent, deposit), [startDate, endDate, rent, deposit]);
85	
86	  const unitItems = units.map((u) => ({ value: u.id, label: u.name }));
87	  const tenantItems = tenants.map((t) => ({ value: t.id, label: `${t.fullName} (${t.email})` }));
88	
89	  async function onSubmit(e: FormEvent<HTMLFormElement>) {
90	    e.preventDefault();
91	    if (submitting) return;
92	    if (!unitId) return void toast.error("Choose a unit.");
93	    if (!tenantId) return void toast.error("Choose a tenant.");
94	    if (preview.kind !== "ok") {
95	      return void toast.error(preview.message);
96	    }
97	
98	    setSubmitting(true);
99	    try {
100	      const res = await callApi<{ id: string }>("/api/leases", {
101	        method: "POST",
102	        body: {
103	          unitId,
104	          tenantId,
105	          startDate,
106	          endDate,
107	          monthlyRentSen: parseRinggitToSen(rent),
108	          depositSen: deposit.trim() === "" ? 0 : parseRinggitToSen(deposit),
109	        },
110	      });
111	      if (!res.ok) {
112	        toast.error(
113	          res.status === 409 ? "This unit already has a lease that overlaps these dates" : res.error,
114	        );
115	        return;
116	      }
117	      toast.success("Lease created.");
118	      router.push(`/leases/${res.data.id}`);
119	    } catch {
120	      toast.error("Something went wrong. Please try again.");
121	    } finally {
122	      setSubmitting(false);
123	    }
124	  }
125	
126	  if (units.length === 0 || tenants.length === 0) {
127	    return (
128	      <p className="rounded-lg border border-dashed p-8 text-center text-sm text-muted-foreground">
129	        {units.length === 0 ? "Your organisation has no units yet." : "Your organisation has no tenants yet."} A lease
130	        needs both a unit and a tenant.
131	      </p>
132	    );
133	  }
134	
135	  const shown = preview.kind === "ok" ? preview.rows.slice(0, MAX_PREVIEW_ROWS) : [];
136	
137	  return (
138	    <div className="grid gap-6 lg:grid-cols-2">
139	      <Card>
140	        <CardHeader>
141	          <CardTitle>Lease details</CardTitle>
142	          <CardDescription>Amounts are in ringgit. Dates are calendar dates.</CardDescription>
143	        </CardHeader>
144	        <CardContent>
145	          <form onSubmit={onSubmit} noValidate className="grid gap-4 sm:grid-cols-2">
146	            <div className="flex flex-col gap-2">
147	              <Label htmlFor="unit">Unit</Label>
148	              <Select value={unitId} items={unitItems} onValueChange={setUnitId} disabled={submitting}>
149	                <SelectTrigger id="unit" className="w-full">
150	                  <SelectValue placeholder="Select a unit" />
151	                </SelectTrigger>
152	                <SelectContent>
153	                  {unitItems.map((u) => (
154	                    <SelectItem key={u.value} value={u.value}>
155	                      {u.label}
156	                    </SelectItem>
157	                  ))}
158	                </SelectContent>
159	              </Select>
160	            </div>
161	
162	            <div className="flex flex-col gap-2">
163	              <Label htmlFor="tenant">Tenant</Label>
164	              <Select value={tenantId} items={tenantItems} onValueChange={setTenantId} disabled={submitting}>
165	                <SelectTrigger id="tenant" className="w-full">
166	                  <SelectValue placeholder="Select a tenant" />
167	                </SelectTrigger>
168	                <SelectContent>
169	                  {tenantItems.map((t) => (
170	                    <SelectItem key={t.value} value={t.value}>
171	                      {t.label}
172	                    </SelectItem>
173	                  ))}
174	                </SelectContent>
175	              </Select>
176	            </div>
177	
178	            <div className="flex flex-col gap-2">
179	              <Label htmlFor="start-date">Start date</Label>
180	              <Input
181	                id="start-date"
182	                type="date"
183	                value={startDate}
184	                onChange={(e) => setStartDate(e.target.value)}
185	                disabled={submitting}
186	              />
187	            </div>
188	
189	            <div className="flex flex-col gap-2">
190	              <Label htmlFor="end-date">End date</Label>
191	              <Input
192	                id="end-date"
193	                type="date"
194	                value={endDate}
195	                onChange={(e) => setEndDate(e.target.value)}
196	                disabled={submitting}
197	              />
198	            </div>
199	
200	            <div className="flex flex-col gap-2">
201	              <Label htmlFor="monthly-rent">Monthly rent (RM)</Label>
202	              <Input
203	                id="monthly-rent"
204	                inputMode="decimal"
205	                autoComplete="off"
206	                placeholder="1,500.00"
207	                value={rent}
208	                onChange={(e) => setRent(e.target.value)}
209	                disabled={submitting}
210	              />
211	            </div>
212	
213	            <div className="flex flex-col gap-2">
214	              <Label htmlFor="deposit">Deposit (RM, optional)</Label>
215	              <Input
216	                id="deposit"
217	                inputMode="decimal"
218	                autoComplete="off"
219	                placeholder="3,000.00"
220	                value={deposit}
221	                onChange={(e) => setDeposit(e.target.value)}
222	                disabled={submitting}
223	              />
224	            </div>
225	
226	            <div className="flex justify-end sm:col-span-2">
227	              <Button type="submit" disabled={submitting}>
228	                {submitting ? "Creating..." : "Create lease"}
229	              </Button>
230	            </div>
231	          </form>
232	        </CardContent>
233	      </Card>
234	
235	      <Card>
236	        <CardHeader>
237	          <CardTitle>Invoice schedule preview</CardTitle>
238	          <CardDescription>The invoices that will be created with this lease.</CardDescription>
239	        </CardHeader>
240	        <CardContent>
241	          {preview.kind === "hint" && (
242	            <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">
243	              {preview.message}
244	            </p>
245	          )}
246	          {preview.kind === "error" && (
247	            <p role="alert" className="rounded-lg border border-destructive/40 p-4 text-sm text-destructive">
248	              {preview.message}
249	            </p>
250	          )}
251	          {preview.kind === "ok" && (
252	            <Table>
253	              <TableHeader>
254	                <TableRow>
255	                  <TableHead>Invoice</TableHead>
256	                  <TableHead>Period</TableHead>
257	                  <TableHead>Due</TableHead>
258	                  <TableHead className="text-right">Amount</TableHead>
259	                </TableRow>
260	              </TableHeader>
261	              <TableBody>
262	                {shown.map((r) => (
263	                  <TableRow key={`${r.kind}-${r.periodIndex ?? "d"}`}>
264	                    <TableCell className="font-medium">{kindLabel(r)}</TableCell>
265	                    <TableCell className="tabular-nums">
266	                      {r.periodStart && r.periodEnd ? `${r.periodStart} to ${r.periodEnd}` : "-"}
267	                    </TableCell>
268	                    <TableCell className="tabular-nums">{r.dueDate}</TableCell>
269	                    <TableCell className="text-right tabular-nums">{formatSen(r.amountSen)}</TableCell>
270	                  </TableRow>
271	                ))}
272	              </TableBody>
273	              <TableFooter>
274	                <TableRow>
275	                  <TableCell colSpan={3} className="font-medium">
276	                    Total ({preview.rows.length} {preview.rows.length === 1 ? "invoice" : "invoices"})
277	                    {preview.rows.length > shown.length && `, first ${shown.length} shown`}
278	                  </TableCell>
279	                  <TableCell className="text-right font-medium tabular-nums" data-testid="schedule-total">
280	                    {formatSen(preview.totalSen)}
281	                  </TableCell>
282	                </TableRow>
283	              </TableFooter>
284	            </Table>
285	          )}
286	        </CardContent>
287	      </Card>
288	    </div>
289	  );
290	}
